/*
 * Draws equipment comparison panel between shop item and party gear in 1x mode.
 */
// FUNCTION: FF7 0x0071a2c1
void __cdecl Menu_DrawShopEquipComparisonPanel1x(unsigned int frameCounter)
{
    int newAttack;
    int armorDef;
    unsigned int colorCode;
    int slot;
    int curAtk;
    int posX;
    int posY;
    int isLowerRow;
    int newDef;
    int entId;

    for (slot = 0; slot < 3; slot++) {
        if (gSavemap.party[slot] == PARTY_CHAR_NONE) {
            continue;
        }
        entId = gSavemap.party[slot];
        posX = entId % 3 * 0x60 + 0xC;
        posY = entId / 3 * 0x1B + 0x9C;
        colorCode = frameCounter & 0x7F;
        if (colorCode > 0x3F) {
            colorCode = 0x3F - (colorCode - 0x40);
        }
        Menu_DrawShopPartyTileHighlight1x(posX, posY, 0x14, 0x1A, colorCode << 2);
    }
    for (slot = 0; slot < 9; slot++) {
        if ((gSavemap.phsVisibilityMask & (1 << slot)) == 0) {
            continue;
        }
        colorCode = slot % 3;
        isLowerRow = slot > 2;
        posX = slot % 3 * 0x60 + 0xC;
        posY = slot / 3 * 0x1B + 0x9C;
        Menu_DrawCharPortraitById1x(posX, posY, 0x14, 0x1A, slot, 0.2f);
        curAtk = g_KernelWeaponDataArray[gSavemap.chars[slot].weapon].attackBonusByte;
        newAttack = curAtk;
        armorDef = g_KernelArmorDataArray[gSavemap.chars[slot].armor].physicalDefense;
        newDef = armorDef;
        entId = g_MenuShopRecords[g_MenuShopIndex].entries[g_MenuShopCursorBlock[1].row + g_MenuShopCursorBlock[1].scrollTop].id;
        switch (g_MenuShopRecords[g_MenuShopIndex].entries[g_MenuShopCursorBlock[1].row + g_MenuShopCursorBlock[1].scrollTop].kind) {
        case MENU_SHOP_ENTRY_ITEM:
            if (entId < 0x80) {
                continue;
            }
            if (entId < 0x100) {
                if (g_KernelWeaponDataArray[(entId - 0x80)].equipMask & (1 << slot)) {
                    newAttack = g_KernelWeaponDataArray[(entId - 0x80)].attackBonusByte;
                } else {
                    continue;
                }
            } else if (entId < 0x120) {
                if (g_KernelArmorDataArray[(entId - 0x100)].equipMask & (1 << slot)) {
                    newDef = g_KernelArmorDataArray[(entId - 0x100)].physicalDefense;
                } else {
                    continue;
                }
            } else if (entId < 0x140) {
                continue;
            }
            break;
        case MENU_SHOP_ENTRY_MATERIA:
            continue;
        case MENU_SHOP_ENTRY_NOTHING:
            continue;
        }
        if (newAttack > curAtk) {
            colorCode = 6;
        } else if (newAttack < curAtk) {
            colorCode = 2;
        } else {
            colorCode = 7;
        }
        Menu_DrawEncodedString1x(posX + 0x18, posY + 0xF, &g_MenuShopTextTable[0x2fa], 5, 0.2f);
        Menu_DrawEncodedString1x(posX + 0x18, posY + 2, &g_MenuShopTextTable[0x2f8], 5, 0.2f);
        Menu_DrawDecimalNumber1x(posX + 0x28, posY + 5, curAtk, 3, 7, 0.2f);
        DrawIconGlyph16_1x(posX + 0x3A, posY + 5, 0xDA, 5, 0.2f);
        Menu_DrawDecimalNumber1x(posX + 0x40, posY + 5, newAttack, 3, colorCode, 0.2f);
        if (newDef > armorDef) {
            colorCode = 6;
        } else if (newDef < armorDef) {
            colorCode = 2;
        } else {
            colorCode = 7;
        }
        Menu_DrawDecimalNumber1x(posX + 0x28, posY + 0x11, armorDef, 3, 7, 0.2f);
        DrawIconGlyph16_1x(posX + 0x3A, posY + 0x11, 0xDA, 5, 0.2f);
        Menu_DrawDecimalNumber1x(posX + 0x40, posY + 0x11, newDef, 3, colorCode, 0.2f);
    }
}

