/*
 * Calculates maximum purchasable item quantity based on current gil.
 */
// FUNCTION: FF7 0x0071a7a9
int __cdecl Menu_ShopGetMaxPurchasableQuantity(void)
{
    /* The partial result lives in esi across the second call: one
       expression, two calls, and VC5 keeps the difference in a
       callee-saved register rather than a slot. */
    return 0x63 - Menu_ShopGetSelectedEntryOwnedCount() - Menu_ShopCountSelectedEntryEquipped();
}

/*
 * Gets owned quantity of currently selected shop item.
 */
// FUNCTION: FF7 0x0071a7c5
int __cdecl Menu_ShopGetSelectedEntryOwnedCount(void)
{
    int result;
    int item;

    item = g_MenuShopRecords[g_MenuShopIndex].entries[g_MenuShopCursorBlock[1].row + g_MenuShopCursorBlock[1].scrollTop].id;
    switch (g_MenuShopRecords[g_MenuShopIndex].entries[g_MenuShopCursorBlock[1].row + g_MenuShopCursorBlock[1].scrollTop].kind) {
    case MENU_SHOP_ENTRY_ITEM:
        result = Savemap_FindItem((unsigned short)item);
        if (result == 0xffff) {
            result = 0;
        } else {
            result = result >> 9;
        }
        break;
    case MENU_SHOP_ENTRY_MATERIA:
        result = Savemap_CountMateriaInStock(item & 0xff);
        break;
    case MENU_SHOP_ENTRY_NOTHING:
        result = 0;
        break;
    }
    return result;
}

/*
 * Counts equipped copies of selected item across active party.
 */
// FUNCTION: FF7 0x0071a873
int __cdecl Menu_ShopCountSelectedEntryEquipped(void)
{
    int scratch;
    unsigned int materiaIndex;
    unsigned int characterIdx;
    int count;
    int itemId;

    count = 0;
    itemId = g_MenuShopRecords[g_MenuShopIndex].entries[g_MenuShopCursorBlock[1].row + g_MenuShopCursorBlock[1].scrollTop].id;
    for (characterIdx = 0; characterIdx < 9; characterIdx++) {
        if ((gSavemap.phsVisibilityMask & (1 << characterIdx)) == 0) {
            continue;
        }
        switch (g_MenuShopRecords[g_MenuShopIndex].entries[g_MenuShopCursorBlock[1].row + g_MenuShopCursorBlock[1].scrollTop].kind) {
        case MENU_SHOP_ENTRY_ITEM:
            if (itemId < 0x80) { /* empty first arm: lib/codegen.h */
            } else if (itemId < 0x100) {
                if (gSavemap.chars[characterIdx].weapon + 0x80 == itemId) {
                    count++;
                }
            } else if (itemId < 0x120) {
                if (gSavemap.chars[characterIdx].armor + 0x100 == itemId) {
                    count++;
                }
            } else if (itemId < 0x140 &&
                       gSavemap.chars[characterIdx].accessory + 0x120 == itemId) {
                count++;
            }
            break;
        case MENU_SHOP_ENTRY_MATERIA:
            for (materiaIndex = 0; materiaIndex < 8; materiaIndex++) {
                if ((gSavemap.chars[characterIdx].weaponMateria[materiaIndex] & 0xff) ==
                    (itemId & 0xff)) {
                    count++;
                }
            }
            for (materiaIndex = 0; materiaIndex < 8; materiaIndex++) {
                if ((gSavemap.chars[characterIdx].armorMateria[materiaIndex] & 0xff) ==
                    (itemId & 0xff)) {
                    count++;
                }
            }
            break;
        case MENU_SHOP_ENTRY_NOTHING:
            scratch = 0;
            break;
        }
    }
    return count;
}

/*
 * Checks if player has available free inventory slot for materia.
 */
// FUNCTION: FF7 0x0071aa5e
int __cdecl Menu_ShopHasFreeMateriaStockSlot(void)
{
    int any;
    int i;

    any = 0;
    for (i = 0; i < 0xC8; i++) {
        if (gSavemap.materia[i] == -1) {
            any = 1;
        }
    }
    return any;
}

