/*
 * Returns non-zero if shop stat delta value is negative.
 */
// FUNCTION: FF7 0x0071ef5d
int __cdecl Menu_ShopValueIsNegative(int value)
{
    return value < 0;
}

/*
 * Returns absolute value of integer shop stat delta.
 */
// FUNCTION: FF7 0x0071ef6b
int __cdecl Menu_ShopAbsValue(int v)
{
    int result;

    if (v < 0) {
        result = 0 - v;
    } else {
        result = v;
    }
    return result;
}

