/*
 * Calculates resell price for specified materia item.
 */
// FUNCTION: FF7 0x0071fcf9
int __cdecl Menu_ShopGetMateriaSellValue(unsigned int packed)
{
    int price;

    if (packed == -1) {
        return 0;
    } else if (g_MenuShopPrices[(packed & 0xFF) + 0x180] == 1) {
        return 1;
    } else {
        price = packed >> 8;
        if (price == 0xFFFFFF) {
            price = g_MenuShopPrices[(packed & 0xFF) + 0x180] * 0x46;
        }
        return price;
    }
}

/*
 * Gets base retail purchase price for specified materia.
 */
// FUNCTION: FF7 0x0071fd5a
int __cdecl Menu_ShopGetMateriaBasePrice(int packed)
{
    int price;

    if (packed == -1) {
        return 0;
    } else if (g_MenuShopPrices[(packed & 0xFF) + 0x180] == 1) {
        return 1;
    } else {
        price = g_MenuShopPrices[(packed & 0xFF) + 0x180] * 0x46;
        return price;
    }
}

/*
 * Counts equipped copies of specified materia across party.
 */
// FUNCTION: FF7 0x0071fda9
int __cdecl Menu_ShopCountMateriaEquipped(unsigned int materiaId)
{
    int characterIdx;
    int slot;
    int n;

    n = 0;
    if (materiaId == 0xff) {
        return 0;
    }
    for (characterIdx = 0; characterIdx < 9; characterIdx++) {
        if ((gSavemap.phsVisibilityMask & (1 << characterIdx)) == 0) {
            continue;
        }
        for (slot = 0; slot < 8; slot++) {
            if ((gSavemap.chars[characterIdx].weaponMateria[slot] & 0xff) ==
                (materiaId & 0xff)) {
                n++;
            }
        }
        for (slot = 0; slot < 8; slot++) {
            if ((gSavemap.chars[characterIdx].armorMateria[slot] & 0xff) ==
                (materiaId & 0xff)) {
                n++;
            }
        }
    }
    return n;
}

/*
 * Counts equipped copies of specified gear across party.
 */
// FUNCTION: FF7 0x0071fe9d
int __cdecl Menu_ShopCountGearEquipped(int gearId)
{
    int num;
    int i;

    num = 0;
    for (i = 0; i < 9; i++) {
        if ((gSavemap.phsVisibilityMask & (1 << i)) == 0) {
            continue;
        }
        if (gearId < 0x80) { /* empty first arm: lib/codegen.h */
        } else if (gearId < 0x100) {
            if (gSavemap.chars[i].weapon + 0x80 == gearId) {
                num++;
            }
        } else if (gearId < 0x120) {
            if (gSavemap.chars[i].armor + 0x100 == gearId) {
                num++;
            }
        } else if (gearId < 0x140) {
            if (gSavemap.chars[i].accessory + 0x120 == gearId) {
                num++;
            }
        }
    }
    return num;
}

